{
  "name": "karpathy-wiki",
  "version": "0.0.0",
  "private": true,
  "description": "Repository tooling for the Karpathy Wiki JavaScript configuration and tests",
  "license": "MIT",
  "type": "module",
  "scripts": {
    "lint": "eslint .",
    "format:check": "oxfmt --check .",
    "format": "oxfmt .",
    "test": "node --test tests/test_wiki_ingest_status.mjs tests/test_contract_fixtures.mjs tests/test_wiki_ingest_batch.mjs tests/test_answer_intake.mjs tests/test_chat_bootstrap.mjs"
  },
  "devDependencies": {
    "@eslint/js": "10.0.1",
    "eslint": "10.14.0",
    "globals": "17.14.0",
    "oxfmt": "0.77.0"
  }
}

{
  "$schema": "https://opencode.ai/config.json",
  "update": "disable",
  "share": "disabled",
  "snapshots": false,
  "skills": ["/etc/opencode/skills"],
  "tool_output": {
    "max_lines": 200,
    "max_bytes": 16384
  },
  "agents": {
    "wiki-ingest": {
      "description": "Bearbeitet eine code-zugelassene Quelle im privaten Entwurf.",
      "mode": "subagent",
      "system": "Bearbeite nur die eine Quelle einer vom Batch-Code zugelassenen Kindsession im privaten Arbeitsverzeichnis (wiki_root: .); niemals ins Live-Wiki schreiben. Nutze für alle Entwurfszugriffe relative Pfade, auch in Patch-Dateiköpfen; konstruiere keine absoluten Entwurfspfade. Absolute Leseziele sind nur die zugewiesene Originalquelle, Live-Wiki-Kontext und Ingest-Skill-Dateien. Der Code sendet Batchdaten als User-Nachricht; ein sichtbarer Eltern-Tool-Aufruf ist nicht erforderlich. Eine batch_id allein erteilt keine Zulassung. Lade wiki-ingest einmal. Nutze Lese- und Editierwerkzeuge, keine Shell, kein Git, keine eigenen Statusabfragen und keine Delegation. Quellenstatus/Widerruf, Git-Prüfungen, Frontmatter, Index, Log und Commit übernimmt Code; ändere index.md/log.md nicht.",
      "permissions": [
        {
          "action": "*",
          "resource": "*",
          "effect": "deny"
        },
        {
          "action": "subagent",
          "resource": "*",
          "effect": "deny"
        },
        {
          "action": "shell",
          "resource": "*",
          "effect": "deny"
        },
        {
          "action": "edit",
          "resource": "sources/*.md",
          "effect": "allow"
        },
        {
          "action": "edit",
          "resource": "entities/*.md",
          "effect": "allow"
        },
        {
          "action": "edit",
          "resource": "concepts/*.md",
          "effect": "allow"
        },
        {
          "action": "edit",
          "resource": "analyses/*.md",
          "effect": "allow"
        },
        {
          "action": "edit",
          "resource": "overview.md",
          "effect": "allow"
        },
        {
          "action": "read",
          "resource": "*",
          "effect": "allow"
        },
        {
          "action": "edit",
          "resource": ".git/*",
          "effect": "deny"
        },
        {
          "action": "edit",
          "resource": "AGENTS.md",
          "effect": "deny"
        },
        {
          "action": "edit",
          "resource": "*/AGENTS.md",
          "effect": "deny"
        },
        {
          "action": "edit",
          "resource": ".opencode/*",
          "effect": "deny"
        },
        {
          "action": "read",
          "resource": "/knowledge/sources/**",
          "effect": "allow"
        },
        {
          "action": "read",
          "resource": "/knowledge/wiki/**",
          "effect": "allow"
        },
        {
          "action": "read",
          "resource": "/knowledge/wiki/AGENTS.md",
          "effect": "allow"
        },
        {
          "action": "read",
          "resource": "/etc/opencode/skills/wiki-ingest/*",
          "effect": "allow"
        },
        {
          "action": "edit",
          "resource": "/knowledge/wiki/.git/**",
          "effect": "deny"
        },
        {
          "action": "edit",
          "resource": "/knowledge/wiki/AGENTS.md",
          "effect": "deny"
        },
        {
          "action": "skill",
          "resource": "wiki-ingest",
          "effect": "allow"
        },
        {
          "action": "external_directory",
          "resource": "/knowledge/sources/**",
          "effect": "allow"
        },
        {
          "action": "external_directory",
          "resource": "/etc/opencode/skills/wiki-ingest/**",
          "effect": "allow"
        },
        {
          "action": "external_directory",
          "resource": "/knowledge/wiki/**",
          "effect": "allow"
        },
        {
          "action": "read",
          "resource": "*.env*",
          "effect": "deny"
        },
        {
          "action": "read",
          "resource": "/knowledge/wiki/.git/**",
          "effect": "deny"
        },
        {
          "action": "read",
          "resource": ".git/*",
          "effect": "deny"
        },
        {
          "action": "edit",
          "resource": "/knowledge/wiki/**/AGENTS.md",
          "effect": "deny"
        },
        {
          "action": "edit",
          "resource": "/knowledge/wiki/.opencode/**",
          "effect": "deny"
        }
      ]
    },
    "wiki-ingest-orchestrator": {
      "description": "Startet den sequenziellen Ingest und verlinkt seinen Bericht.",
      "mode": "all",
      "system": "Lade wiki-ingest-orchestrator. Starte wiki_ingest_batch einmal. Code verarbeitet jede Quelle in einer frischen Session und einem privaten Entwurf; isolierte Fehler werden berichtet, nicht automatisch wiederholt. Keine eigenen Änderungen oder Worker-Delegation. Nenne offene Quellen und verlinke den privaten Bericht. Nur ausdrücklich gewünschte Wiederaufnahme einer unterbrochenen Veröffentlichung verwendet batch_id; sie startet keine Worker.",
      "permissions": [
        {
          "action": "read",
          "resource": "/knowledge/incoming/ingest-journal/**",
          "effect": "deny"
        },
        {
          "action": "read",
          "resource": "/knowledge/incoming/ingest-journal/batches/batch-*/report.md",
          "effect": "allow"
        },
        {
          "action": "grep",
          "resource": "*",
          "effect": "deny"
        },
        {
          "action": "glob",
          "resource": "*",
          "effect": "deny"
        },
        {
          "action": "edit",
          "resource": "*",
          "effect": "deny"
        },
        {
          "action": "shell",
          "resource": "*",
          "effect": "deny"
        },
        {
          "action": "webfetch",
          "resource": "*",
          "effect": "deny"
        },
        {
          "action": "websearch",
          "resource": "*",
          "effect": "deny"
        },
        {
          "action": "subagent",
          "resource": "*",
          "effect": "deny"
        },
        {
          "action": "wiki_ingest_batch",
          "resource": "*",
          "effect": "allow"
        },
        {
          "action": "ingest_recovery",
          "resource": "*",
          "effect": "ask"
        }
      ]
    },
    "wiki-lint": {
      "description": "Prüft und wartet das Wiki.",
      "mode": "subagent",
      "system": "Bearbeite ausschließlich Prüf- und Wartungsaufträge für das Wiki. Delegiere nicht erneut. Lade einmal den Skill wiki-lint, befolge ihn vollständig und führe den Auftrag selbst aus.",
      "permissions": [
        {
          "action": "subagent",
          "resource": "*",
          "effect": "deny"
        },
        {
          "action": "shell",
          "resource": "*",
          "effect": "allow"
        }
      ]
    },
    "wiki-analysis": {
      "description": "Analysiert Fragen anhand des Wikis und aktueller wissenschaftlicher Internetquellen.",
      "mode": "subagent",
      "system": "Bearbeite ausschließlich ausdrücklich angeforderte wissenschaftliche Analysen. Delegiere nicht erneut. Lade einmal den Skill wiki-analysis, befolge ihn vollständig und führe den Auftrag selbst aus.",
      "permissions": [
        {
          "action": "edit",
          "resource": "*",
          "effect": "deny"
        },
        {
          "action": "shell",
          "resource": "*",
          "effect": "deny"
        },
        {
          "action": "subagent",
          "resource": "*",
          "effect": "deny"
        }
      ]
    },
    "wiki-analysis-save": {
      "description": "Speichert eine fertige Analyse als Wiki-Seite mit verlinkbarer Druckansicht.",
      "mode": "subagent",
      "system": "Bearbeite ausschließlich Aufträge, eine fertige Analyse als Wiki-Seite zu speichern. Delegiere nicht erneut. Lade einmal den Skill wiki-analysis-save, befolge ihn vollständig und führe den Auftrag selbst aus.",
      "permissions": [
        {
          "action": "subagent",
          "resource": "*",
          "effect": "deny"
        },
        {
          "action": "shell",
          "resource": "*",
          "effect": "allow"
        }
      ]
    }
  },
  "commands": {
    "ingest": {
      "description": "Quelle einlesen",
      "agent": "wiki-ingest-orchestrator",
      "subagent": false,
      "template": "Lade wiki-ingest-orchestrator. Verarbeite nur die ausdrücklich angeforderte neue/geänderte Quelle über wiki_ingest_batch mit source_path aus wiki_ingest_status. Berichte Quellenbezeichnung, Kurztitel, Status und 1–5 Sätze zu Änderungen und Unklarheiten aus sources; verlinke den privaten Bericht. Auftrag: $ARGUMENTS"
    },
    "ingest-new": {
      "description": "Alle neuen und geänderten Quellen einlesen",
      "agent": "wiki-ingest-orchestrator",
      "subagent": false,
      "template": "Lade wiki-ingest-orchestrator. Starte alle neuen und geänderten Quellen unter /knowledge/sources einmal mit wiki_ingest_batch. Das Tool verarbeitet jede Quelle einmal in einer frischen Session und einem privaten Entwurf; isolierte Fehler halten unabhängige Quellen nicht auf. Keine automatischen Wiederholungen oder Reparaturfragen. Nichts zurücksetzen. Berichte je Eintrag aus sources Quellenbezeichnung, Kurztitel, Status und 1–5 Sätze zu Änderungen und Unklarheiten; nenne sources_omitted, falls weitere Einträge nur im Bericht stehen. Verlinke den privaten Bericht und nenne offene Arbeit sowie nötige Nutzermaßnahmen bei Kontextgrenzen."
    },
    "lint": {
      "description": "Wiki prüfen",
      "agent": "wiki-lint",
      "subagent": true,
      "template": "Lade den Skill wiki-lint. Prüfe standardmäßig das gesamte Wiki und berichte die Befunde. Beginne auch ohne zusätzliche Anweisungen mit der Prüfung. Zusätzliche Anweisungen können den Prüfumfang einschränken. Ändere keine Dateien und erstelle keinen Commit, außer wenn ausdrücklich Reparaturen beauftragt werden; beachte dabei die Sicherheits- und Bestätigungsregeln des Skills. Zusätzliche Anweisungen (optional): $ARGUMENTS"
    },
    "analysis": {
      "description": "Wissenschaftliche Analyse mit Internetquellen",
      "agent": "wiki-analysis",
      "subagent": false,
      "template": "$ARGUMENTS"
    },
    "analysis-save": {
      "description": "Analyse ins Wiki aufnehmen (Seite, Index, Log und Druckansicht)",
      "agent": "build",
      "subagent": false,
      "template": "Nimm die fertige Analyse ins Wiki auf (Seite, Index, Log und Druckansicht): Finde im bisherigen Gespräch die letzte vollständige Analyse einschließlich späterer Korrekturen. Falls der folgende Auftrag selbst einen vollständigen Analysetext enthält, verwende stattdessen diesen. Prüfe bei einer Analyse aus einem Subagenten-Ergebnis auf Kürzungsmarker ([showing ...; full output saved to ...]). Lies in diesem Fall die vollständige gespeicherte Tool-Ausgabe stückweise über den read-Befehl; wenn sie nicht vollständig wiederherstellbar ist, speichere nichts und melde den Grund. Übergib nur den vollständigen zu speichernden Text an den Subagenten wiki-analysis-save, nicht nur einen Verweis auf das Gespräch. Ist keine fertige Analyse vorhanden, speichere nichts und melde das. Auftrag: $ARGUMENTS"
    },
    "answer-save": {
      "description": "Bestätigte Antworten in den lokalen Eingang speichern",
      "agent": "build",
      "subagent": false,
      "template": "Speichere die in diesem Gespräch zuletzt ausdrücklich bestätigten Antworten als neue Eingangsdatei unter /knowledge/incoming/answers. Lade den Skill wiki-gap-review und führe ausschließlich dessen Schritt 1 (Lokal speichern) für diese Antworten aus. Ohne ausdrücklich bestätigte, tatsächlich beantwortete Frage speichere nichts und melde das. Vorhandene Entwürfe weder lesen noch ändern; niemals unter /knowledge/sources schreiben. Auftrag: $ARGUMENTS"
    },
    "gap-review": {
      "description": "Wiki-Lücken prüfen, Fragen beantworten und bestätigte Antworten einreichen",
      "agent": "build",
      "subagent": false,
      "template": "Lade den Skill wiki-gap-review und führe eine interaktive Lückenprüfung durch. Prüfe zunächst ausschließlich lesend; halte nummerierte Fragen und Antworten über die weiteren Gesprächsrunden fest. Reiche erst nach ausdrücklicher Bestätigung bestätigte Antworten über den lokalen Eingang und den Anbieter ein. Auftrag: $ARGUMENTS"
    }
  },
  "permissions": [
    {
      "action": "*",
      "resource": "*",
      "effect": "deny"
    },
    {
      "action": "read",
      "resource": "*",
      "effect": "allow"
    },
    {
      "action": "read",
      "resource": "*.env",
      "effect": "deny"
    },
    {
      "action": "read",
      "resource": "*.env.*",
      "effect": "deny"
    },
    {
      "action": "read",
      "resource": "*.env.example",
      "effect": "allow"
    },
    {
      "action": "edit",
      "resource": "*",
      "effect": "allow"
    },
    {
      "action": "edit",
      "resource": ".git/**",
      "effect": "deny"
    },
    {
      "action": "edit",
      "resource": "/knowledge/wiki/.git/**",
      "effect": "deny"
    },
    {
      "action": "edit",
      "resource": "/knowledge/sources/**",
      "effect": "deny"
    },
    {
      "action": "edit",
      "resource": "/knowledge/incoming/ingest-journal/**",
      "effect": "deny"
    },
    {
      "action": "edit",
      "resource": "/home/opencode/.local/share/opencode/tool-output/**",
      "effect": "deny"
    },
    {
      "action": "edit",
      "resource": "/etc/opencode/skills/**",
      "effect": "deny"
    },
    {
      "action": "glob",
      "resource": "*",
      "effect": "allow"
    },
    {
      "action": "grep",
      "resource": "*",
      "effect": "allow"
    },
    {
      "action": "question",
      "resource": "*",
      "effect": "allow"
    },
    {
      "action": "subagent",
      "resource": "*",
      "effect": "allow"
    },
    {
      "action": "webfetch",
      "resource": "*",
      "effect": "allow"
    },
    {
      "action": "websearch",
      "resource": "*",
      "effect": "allow"
    },
    {
      "action": "skill",
      "resource": "wiki-analysis",
      "effect": "allow"
    },
    {
      "action": "skill",
      "resource": "wiki-analysis-save",
      "effect": "allow"
    },
    {
      "action": "skill",
      "resource": "wiki-gap-review",
      "effect": "allow"
    },
    {
      "action": "skill",
      "resource": "wiki-ingest",
      "effect": "allow"
    },
    {
      "action": "skill",
      "resource": "wiki-ingest-orchestrator",
      "effect": "allow"
    },
    {
      "action": "skill",
      "resource": "wiki-lint",
      "effect": "allow"
    },
    {
      "action": "wiki_ingest_status",
      "resource": "*",
      "effect": "allow"
    },
    {
      "action": "wiki_ingest_diagnostics",
      "resource": "*",
      "effect": "allow"
    },
    {
      "action": "wiki_ingest_batch",
      "resource": "*",
      "effect": "deny"
    },
    {
      "action": "external_directory",
      "resource": "/knowledge/incoming/answers/**",
      "effect": "allow"
    },
    {
      "action": "external_directory",
      "resource": "/knowledge/sources/**",
      "effect": "allow"
    },
    {
      "action": "external_directory",
      "resource": "/knowledge/incoming/ingest-journal/**",
      "effect": "allow"
    },
    {
      "action": "external_directory",
      "resource": "/home/opencode/.local/share/opencode/tool-output/**",
      "effect": "allow"
    },
    {
      "action": "external_directory",
      "resource": "/etc/opencode/skills/wiki-analysis-save/**",
      "effect": "allow"
    }
  ]
}

{
  "name": "karpathy-wiki-chat",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "dependencies": {
    "@openchamber/web": "2.6.1"
  }
}
